"""Bounded diagnostic data only; no exception text, locals, URLs or absolute paths."""
from pathlib import Path
ALLOWED_CODES = frozenset(['SEMANTIC_EXPOSURE_ARRAYS_INVALID', 'SEMANTIC_EXPOSURE_GEOMETRY_CHANGED', 'SEMANTIC_EXPOSURE_GEOMETRY_HASH', 'SEMANTIC_EXPOSURE_GEOMETRY_INVALID', 'SEMANTIC_EXPOSURE_ICC_UNQUALIFIED', 'SEMANTIC_EXPOSURE_PROTECTED_OVERLAP', 'SEMANTIC_EXPOSURE_RESOURCE_PROFILE', 'SEMANTIC_EXPOSURE_TRANSFORM_UNSAFE', 'SEMANTIC_PREVIEW_ADMISSION_DENIED', 'SEMANTIC_PREVIEW_ADOPTION_BINDING_INVALID', 'SEMANTIC_PREVIEW_ADOPTION_DENIED', 'SEMANTIC_PREVIEW_ADOPTION_DOCUMENT_INVALID', 'SEMANTIC_PREVIEW_ARTIFACT_ALIAS', 'SEMANTIC_PREVIEW_BINDING_INVALID', 'SEMANTIC_PREVIEW_INSTALLATION_REQUIRED', 'SEMANTIC_PREVIEW_MEDIA_ADMISSION_DENIED', 'SEMANTIC_PREVIEW_MEDIA_ICC_UNQUALIFIED', 'SEMANTIC_PREVIEW_MEDIA_INVALID', 'SEMANTIC_RETOUCH_ARTIFACT_ALIAS', 'SEMANTIC_RETOUCH_COMPUTE_BINDING_INVALID', 'SEMANTIC_RETOUCH_CONTEXT_ALIAS', 'SEMANTIC_RETOUCH_CONTEXT_BINDING_INVALID', 'SEMANTIC_RETOUCH_CONTEXT_BYTES_INVALID', 'SEMANTIC_RETOUCH_FACE_BYTES_INVALID', 'SEMANTIC_RETOUCH_FACE_CONTEXT_INVALID', 'SEMANTIC_RETOUCH_FACE_EVIDENCE_INVALID', 'SEMANTIC_RETOUCH_FACE_GEOMETRY_INVALID', 'SEMANTIC_RETOUCH_FACE_INSTALLATION_REQUIRED', 'SEMANTIC_RETOUCH_FACE_ORIGIN_STALE', 'SEMANTIC_RETOUCH_FACE_SOURCE_INVALID', 'SEMANTIC_RETOUCH_HDR_UNSUPPORTED', 'SEMANTIC_RETOUCH_INPUTS_INVALID', 'SEMANTIC_RETOUCH_INPUT_INDEX_REQUIRED', 'SEMANTIC_RETOUCH_INSTALLATION_REQUIRED', 'SEMANTIC_RETOUCH_LEASE_CHANGED', 'SEMANTIC_RETOUCH_OUTPUT_CLOSURE_INVALID', 'SEMANTIC_RETOUCH_OUTPUT_INVALID', 'SEMANTIC_RETOUCH_PRESERVATION_INVALID', 'SEMANTIC_RETOUCH_QUALIFICATION_DENIED', 'SEMANTIC_RETOUCH_RESOURCE_PROFILE', 'SEMANTIC_RETOUCH_RESULT_ALIAS', 'SEMANTIC_RETOUCH_RESULT_BINDING_INVALID', 'SEMANTIC_RETOUCH_RESULT_BYTES_INVALID', 'SEMANTIC_RETOUCH_TASK_INVALID', 'SEMANTIC_RETOUCH_UNDECLARED_INPUT', 'SEMANTIC_RETOUCH_ZERO_STRENGTH_CHANGED'])
def safe_execution_error(error,root):
 root=Path(root).resolve();frames=[];tb=error.__traceback__
 while tb is not None:
  try:
   path=Path(tb.tb_frame.f_code.co_filename).resolve().relative_to(root)
   if path.parts and path.parts[0] in ('workers','tests'):
    frames.append({'path':path.as_posix(),'line':tb.tb_lineno})
  except (ValueError,OSError):pass
  tb=tb.tb_next
 code=error.args[0] if type(error) is ValueError and len(error.args)==1 and type(error.args[0]) is str and error.args[0] in ALLOWED_CODES else None
 return {'type':type(error).__name__ if type(error) in (ValueError,TypeError,RuntimeError,AssertionError) else 'OtherException','code':code,'frames':frames[-12:]}
